text:
{
  "__comment": "These blocks allow grottols to dig and disappear. Blocks that copy their properties from these tagged blocks will also be allowed.",
  "replace": false,
  "values": [
    {
      "id": "#mowziesmobs:geomancy_useable",
      "required": false
    }
  ]
}

{
  "__comment": "These blocks can be used with Geomancy abilities. Blocks that copy their properties from these tagged blocks will also be useable.",
  "replace": false,
  "values": [
    "#mowziesmobs:geomancy_useable",
    "minecraft:snow",
    "minecraft:snow_block",
    "minecraft:packed_ice"
  ]
}

{
  "__comment": "These items will be able to damage grottols even if they cannot mine diamond ore.",
  "replace": false,
  "values": [
    {
      "id": "cagedmobs:dnasamplerdiamond",
      "required": false
    },
    {
      "id": "cagedmobs:dnasamplernetherite",
      "required": false
    }
  ]
}

{
  "__comment": "These items will count as hand weapons for the Geomancer Beads buff.",
  "replace": false,
  "values": [
    {
      "id": "mowziesmobs:earthrend_gauntlet",
      "required": false
    }
  ]
}

